class Solution { public: int minimumEffortPath(vector<vector<int>>& heights){int rows=heights.size(),cols=heights[0].size();vector<vector<int>> effort(rows,vector<int>(cols,INT_MAX));priority_queue<array<int,3>,vector<array<int,3>>,greater<array<int,3>>> pending;effort[0][0]=0;pending.push({0,0,0});int directions[4][2]={{1,0},{-1,0},{0,1},{0,-1}};while(!pending.empty()){auto [cost,row,col]=pending.top();pending.pop();if(cost!=effort[row][col])continue;if(row==rows-1&&col==cols-1)return cost;for(auto& direction:directions){int nextRow=row+direction[0],nextCol=col+direction[1];if(nextRow<0||nextRow>=rows||nextCol<0||nextCol>=cols)continue;int candidate=max(cost,abs(heights[row][col]-heights[nextRow][nextCol]));if(candidate<effort[nextRow][nextCol]){effort[nextRow][nextCol]=candidate;pending.push({candidate,nextRow,nextCol});}}}return 0;} };
